corrected_code:
const express = require('express');
const db = require('../db');

const app = express();

app.get('/api/arweave/receipts/:txId', async (req, res) => {
  const { txId } = req.params;

  // Ensure transaction belongs to caller's team or user account
  const receipt = await db('arweave_uploads')
    .where({ transaction_id: txId, user_id: req.user.id })
    .first();

  if (!receipt) {
    return res.status(404).json({ error: 'Receipt not found or access denied' });
  }

  return res.json({
    transactionId: receipt.transaction_id,
    bundleBlock: receipt.bundle_block,
    dataTags: receipt.data_tags,
    payloadChecksum: receipt.checksum,
    payerWallet: receipt.payer_wallet
  });
});

module.exports = app;
